import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.BN2sqjC1.js";const d=JSON.parse('{"title":"Template e note giornaliere","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/template-note-giornaliere.md","filePath":"user-guide/template-note-giornaliere.md"}'),r={name:"user-guide/template-note-giornaliere.md"};function n(l,e,s,m,c,p){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="template-e-note-giornaliere" tabindex="-1">Template e note giornaliere <a class="header-anchor" href="#template-e-note-giornaliere" aria-label="Permalink to &quot;Template e note giornaliere&quot;">​</a></h1><h2 id="note-giornaliere" tabindex="-1">Note giornaliere <a class="header-anchor" href="#note-giornaliere" aria-label="Permalink to &quot;Note giornaliere&quot;">​</a></h2><p><em>Apri la nota giornaliera di oggi</em> crea (se manca) e apre la nota del giorno. In <em>Impostazioni → Note giornaliere e template</em> scegliete la <strong>cartella</strong>, il <strong>formato della data</strong> (es. <code>YYYY-MM-DD</code>) e il <strong>template</strong> da usare per le nuove note. <em>Nota giornaliera precedente/successiva</em> si spostano tra i giorni. Se aprite il comando da una nota che non è giornaliera, l&#39;app vi ricorda di controllare cartella e formato.</p><h2 id="template" tabindex="-1">Template <a class="header-anchor" href="#template" aria-label="Permalink to &quot;Template&quot;">​</a></h2><p>I template sono note in una cartella dedicata (impostabile; se la cartella è vuota compare un avviso). <em>Inserisci template</em> li inserisce nella nota corrente; <em>Nuova nota da template</em> chiede il nome e crea la nota. I segnaposto supportati nei template (data, ora, titolo) sono elencati in <em>Impostazioni → Note giornaliere e template</em>.</p><h2 id="note-uniche" tabindex="-1">Note uniche <a class="header-anchor" href="#note-uniche" aria-label="Permalink to &quot;Note uniche&quot;">​</a></h2><p><em>Nuova nota unica</em> crea una nota con un nome basato sull&#39;orario (utile per appunti veloci a prova di collisione).</p><h2 id="unire-ed-estrarre" tabindex="-1">Unire ed estrarre <a class="header-anchor" href="#unire-ed-estrarre" aria-label="Permalink to &quot;Unire ed estrarre&quot;">​</a></h2><ul><li><em>Unisci la nota corrente in un&#39;altra nota</em>: aggiunge il contenuto, <strong>reindirizza i link</strong> e sposta la nota originale nel cestino (l&#39;app mostra un riepilogo e chiede conferma).</li><li><em>Estrai la selezione in una nuova nota</em>: sposta il testo selezionato in una nota nuova e lascia un link al suo posto.</li><li><em>Apri una nota casuale</em>: per riscoprire materiale dimenticato.</li></ul>',9)])])}const g=a(r,[["render",n]]);export{d as __pageData,g as default};
